def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([0]), fmt([3, 3]), fmt([1, 2, 3, 4]), fmt([-1, -2, -3, -4, -5]), fmt([0, 0, 0]),
             fmt([10**9] * 5), fmt([-10**9, 10**9, -10**9, 10**9])]
    for n in (2, 3, 4, 5, 6, 7, 10, 15, 25):
        for _ in range(2):
            tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(1000)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9 if i % 2 == 0 else -10**9 for i in range(100000)]))
    tests.append(fmt([7] * 100000))
    return tests
